static void qiban_ui_refresh_map(struct qiban_ui_s *ui)
{
  char map_status[160];

  qiban_ui_build_map_status(ui, map_status, sizeof(map_status));

  if (ui->map_state.ready)
    {
      if (strcmp(ui->active_map_path, ui->map_state.image_path) != 0 ||
          ui->active_map_updated_at != ui->map_state.updated_at)
        {
          lv_image_cache_drop(ui->map_state.image_path);
          lv_image_set_src(ui->map_page_image, ui->map_state.image_path);
          snprintf(ui->active_map_path, sizeof(ui->active_map_path), "%s",
                   ui->map_state.image_path);
          ui->active_map_updated_at = ui->map_state.updated_at;
        }

      lv_obj_clear_flag(ui->map_page_image, LV_OBJ_FLAG_HIDDEN);
      lv_obj_add_flag(ui->map_page_placeholder, LV_OBJ_FLAG_HIDDEN);
      lv_obj_clear_flag(ui->map_page_status_label, LV_OBJ_FLAG_HIDDEN);
      lv_label_set_text(ui->map_page_status_label, map_status);
      qiban_ui_refresh_map_overlay(ui);
    }
  else
    {
      ui->active_map_path[0] = '\0';
      ui->active_map_updated_at = 0;
      lv_obj_add_flag(ui->map_page_image, LV_OBJ_FLAG_HIDDEN);
      lv_obj_clear_flag(ui->map_page_placeholder, LV_OBJ_FLAG_HIDDEN);
      lv_obj_add_flag(ui->map_page_status_label, LV_OBJ_FLAG_HIDDEN);
      if (ui->map_route_line != NULL)
        {
          lv_obj_add_flag(ui->map_route_line, LV_OBJ_FLAG_HIDDEN);
        }
      if (ui->map_info_panel != NULL)
        {
          lv_obj_add_flag(ui->map_info_panel, LV_OBJ_FLAG_HIDDEN);
        }
      lv_label_set_text(ui->map_page_placeholder, map_status);
    }
}

static lv_coord_t qiban_ui_clamp_coord(lv_coord_t value, lv_coord_t min_value,
                                       lv_coord_t max_value)
{
  if (value < min_value)
    {
      return min_value;
    }

  if (value > max_value)
    {
      return max_value;
    }

  return value;
}

static void qiban_ui_project_map_point(struct qiban_ui_s *ui,
                                       double longitude,
                                       double latitude,
                                       lv_coord_t *x_out,
                                       lv_coord_t *y_out)
{
  double min_lon;
  double max_lon;
  double min_lat;
  double max_lat;
  double lon_span;
  double lat_span;
  double x_ratio;
  double y_ratio;
  lv_coord_t width;
  lv_coord_t height;
  lv_coord_t usable_width;
  lv_coord_t usable_height;

  width = lv_obj_get_width(ui->map_frame);
  height = lv_obj_get_height(ui->map_frame);
  usable_width = width - (QIBAN_MAP_MARKER_PAD * 2);
  usable_height = height - (QIBAN_MAP_MARKER_PAD * 2);

  min_lon = ui->map_state.center_longitude - 0.020;
  max_lon = ui->map_state.center_longitude + 0.020;
  min_lat = ui->map_state.center_latitude - 0.015;
  max_lat = ui->map_state.center_latitude + 0.015;

  if (ui->map_state.has_route)
    {
      if (ui->map_state.route_start_longitude < min_lon)
        {
          min_lon = ui->map_state.route_start_longitude;
        }

      if (ui->map_state.route_end_longitude < min_lon)
        {
          min_lon = ui->map_state.route_end_longitude;
        }

      if (ui->map_state.route_start_longitude > max_lon)
        {
          max_lon = ui->map_state.route_start_longitude;
        }

      if (ui->map_state.route_end_longitude > max_lon)
        {
          max_lon = ui->map_state.route_end_longitude;
        }

      if (ui->map_state.route_start_latitude < min_lat)
        {
          min_lat = ui->map_state.route_start_latitude;
        }

      if (ui->map_state.route_end_latitude < min_lat)
        {
          min_lat = ui->map_state.route_end_latitude;
        }

      if (ui->map_state.route_start_latitude > max_lat)
        {
          max_lat = ui->map_state.route_start_latitude;
        }

      if (ui->map_state.route_end_latitude > max_lat)
        {
          max_lat = ui->map_state.route_end_latitude;
        }
    }

  lon_span = max_lon - min_lon;
  lat_span = max_lat - min_lat;
  if (lon_span < 0.000001)
    {
      lon_span = 0.000001;
    }

  if (lat_span < 0.000001)
    {
      lat_span = 0.000001;
    }

  x_ratio = (longitude - min_lon) / lon_span;
  y_ratio = (max_lat - latitude) / lat_span;
  if (x_ratio < 0.0)
    {
      x_ratio = 0.0;
    }
  else if (x_ratio > 1.0)
    {
      x_ratio = 1.0;
    }

  if (y_ratio < 0.0)
    {
      y_ratio = 0.0;
    }
  else if (y_ratio > 1.0)
    {
      y_ratio = 1.0;
    }

  *x_out = QIBAN_MAP_MARKER_PAD + (lv_coord_t)(x_ratio * usable_width);
  *y_out = QIBAN_MAP_MARKER_PAD + (lv_coord_t)(y_ratio * usable_height);
}

static void qiban_ui_refresh_map_overlay(struct qiban_ui_s *ui)
{
  lv_coord_t start_x;
  lv_coord_t start_y;
  lv_coord_t end_x;
  lv_coord_t end_y;

  if (ui->map_route_line == NULL || ui->map_info_panel == NULL)
    {
      return;
    }

  if (ui->map_state.center_longitude == 0.0 && ui->map_state.center_latitude == 0.0)
    {
      lv_obj_add_flag(ui->map_info_panel, LV_OBJ_FLAG_HIDDEN);
    }
  else
    {
      lv_label_set_text_fmt(ui->map_meta_label,
                            "中心 %.5f, %.5f  Z%d  %s",
                            ui->map_state.center_longitude,
                            ui->map_state.center_latitude,
                            ui->map_state.zoom,
                            ui->map_state.mode[0] != '\0' ?
                            ui->map_state.mode : "point");
      lv_obj_clear_flag(ui->map_info_panel, LV_OBJ_FLAG_HIDDEN);
      lv_obj_move_foreground(ui->map_info_panel);
    }

  if (!ui->map_state.has_route)
    {
      lv_obj_add_flag(ui->map_route_line, LV_OBJ_FLAG_HIDDEN);
      return;
    }

  qiban_ui_project_map_point(ui,
                             ui->map_state.route_start_longitude,
                             ui->map_state.route_start_latitude,
                             &start_x, &start_y);
  qiban_ui_project_map_point(ui,
                             ui->map_state.route_end_longitude,
                             ui->map_state.route_end_latitude,
                             &end_x, &end_y);

  lv_point_precise_set(&ui->map_route_points[0], start_x, start_y);
  lv_point_precise_set(&ui->map_route_points[1], end_x, end_y);
  lv_line_set_points_mutable(ui->map_route_line, ui->map_route_points, 2);
  lv_obj_clear_flag(ui->map_route_line, LV_OBJ_FLAG_HIDDEN);
  lv_obj_move_foreground(ui->map_route_line);
}

static void qiban_ui_refresh_location_marker(struct qiban_ui_s *ui)
{
  lv_coord_t width;
  lv_coord_t height;
  lv_coord_t usable_width;
  lv_coord_t usable_height;
  lv_coord_t x;
  lv_coord_t y;

  if (ui->location_marker == NULL || ui->map_frame == NULL)
    {
      return;
    }

  if (!ui->location_state.valid ||
      (ui->map_state.center_longitude == 0.0 &&
       ui->map_state.center_latitude == 0.0))
    {
      lv_obj_add_flag(ui->location_marker, LV_OBJ_FLAG_HIDDEN);
      if (ui->location_label != NULL)
        {
          lv_obj_add_flag(ui->location_label, LV_OBJ_FLAG_HIDDEN);
        }
      return;
    }

  width = lv_obj_get_width(ui->map_frame);
  height = lv_obj_get_height(ui->map_frame);
  usable_width = width - (QIBAN_MAP_MARKER_PAD * 2);
  usable_height = height - (QIBAN_MAP_MARKER_PAD * 2);
  if (usable_width <= 0 || usable_height <= 0)
    {
      return;
    }

  qiban_ui_project_map_point(ui,
                             ui->location_state.longitude,
                             ui->location_state.latitude,
                             &x, &y);
  x -= QIBAN_MAP_MARKER_SIZE / 2;
  y -= QIBAN_MAP_MARKER_SIZE / 2;
  x = qiban_ui_clamp_coord(x, 0, width - QIBAN_MAP_MARKER_SIZE);
  y = qiban_ui_clamp_coord(y, 0, height - QIBAN_MAP_MARKER_SIZE);

  lv_obj_set_pos(ui->location_marker, x, y);
  lv_obj_clear_flag(ui->location_marker, LV_OBJ_FLAG_HIDDEN);
  lv_obj_move_foreground(ui->location_marker);

  if (ui->location_label != NULL)
    {
      lv_label_set_text(ui->location_label, "我");
      lv_obj_align_to(ui->location_label, ui->location_marker,
                      LV_ALIGN_OUT_TOP_LEFT, -4, -4);
      lv_obj_clear_flag(ui->location_label, LV_OBJ_FLAG_HIDDEN);
      lv_obj_move_foreground(ui->location_label);
    }
}

