    long value; /* shell 输入的默认路线序号，用户按 1 开始计数 */
    uint32_t route_count; /* 默认路线数组内可用路线数量 */

    if(route_index == NULL) {
        return false;
    }

    route_count = (uint32_t)(sizeof(ui_NavDemoRoutes) / sizeof(ui_NavDemoRoutes[0]));
    if(text == NULL) {
        *route_index = 0U;
