static void qiban_ui_sync_offline_route(struct qiban_ui_s *ui)
{
  int start_lon_e7;
  int start_lat_e7;
  int end_lon_e7;
  int end_lat_e7;
  int zoom;
  uint32_t total_distance_m;
  bool has_route;

  if (ui == NULL || ui->map_widget == NULL)
    {
      return;
    }

  has_route = false;
  start_lon_e7 = 0;
  start_lat_e7 = 0;
  end_lon_e7 = 0;
  end_lat_e7 = 0;
  total_distance_m = 0;

  if (ui->nav_state.active &&
      (ui->nav_state.start_longitude != 0.0 ||
       ui->nav_state.start_latitude != 0.0 ||
       ui->nav_state.end_longitude != 0.0 ||
       ui->nav_state.end_latitude != 0.0))
    {
      has_route = true;
      start_lon_e7 = qiban_ui_coord_to_e7(ui->nav_state.start_longitude);
      start_lat_e7 = qiban_ui_coord_to_e7(ui->nav_state.start_latitude);
      end_lon_e7 = qiban_ui_coord_to_e7(ui->nav_state.end_longitude);
      end_lat_e7 = qiban_ui_coord_to_e7(ui->nav_state.end_latitude);
      total_distance_m = ui->nav_state.total_distance_m > 0 ?
                         (uint32_t)ui->nav_state.total_distance_m :
                         (ui->nav_state.remaining_distance_m > 0 ?
                          (uint32_t)ui->nav_state.remaining_distance_m : 1U);
    }
  else if (ui->map_state.has_route)
    {
      has_route = true;
      start_lon_e7 = qiban_ui_coord_to_e7(ui->map_state.route_start_longitude);
      start_lat_e7 = qiban_ui_coord_to_e7(ui->map_state.route_start_latitude);
      end_lon_e7 = qiban_ui_coord_to_e7(ui->map_state.route_end_longitude);
      end_lat_e7 = qiban_ui_coord_to_e7(ui->map_state.route_end_latitude);
      total_distance_m = 1U;
    }

  if (!has_route)
    {
      if (ui->map_route_active)
        {
          lv_offline_map_track_clear(ui->map_widget);
          ui->map_route_total_distance_m = 0;
          ui->map_route_active = 0;
        }
      return;
    }

  if (ui->map_route_active &&
      ui->map_route_start_lon_e7 == start_lon_e7 &&
      ui->map_route_start_lat_e7 == start_lat_e7 &&
      ui->map_route_end_lon_e7 == end_lon_e7 &&
      ui->map_route_end_lat_e7 == end_lat_e7 &&
      ui->map_route_total_distance_m == total_distance_m)
    {
      return;
    }

  zoom = qiban_ui_effective_map_zoom(ui);
  lv_offline_map_track_clear(ui->map_widget);
  lv_offline_map_track_begin_batch(ui->map_widget);
  if (!lv_offline_map_track_add_lonlat_e7_with_distance(ui->map_widget,
                                                        start_lon_e7,
                                                        start_lat_e7,
                                                        zoom,
                                                        0U) ||
      !lv_offline_map_track_add_lonlat_e7_with_distance(ui->map_widget,
                                                        end_lon_e7,
                                                        end_lat_e7,
                                                        zoom,
                                                        total_distance_m))
    {
      lv_offline_map_track_end_batch(ui->map_widget);
      lv_offline_map_track_clear(ui->map_widget);
      ui->map_route_active = 0;
      return;
    }

  lv_offline_map_track_end_batch(ui->map_widget);
  ui->map_route_start_lon_e7 = start_lon_e7;
  ui->map_route_start_lat_e7 = start_lat_e7;
  ui->map_route_end_lon_e7 = end_lon_e7;
  ui->map_route_end_lat_e7 = end_lat_e7;
  ui->map_route_total_distance_m = total_distance_m;
  ui->map_route_active = 1;
}

static void qiban_ui_refresh_location_marker(struct qiban_ui_s *ui)
{
  int lon_e7;
  int lat_e7;
  int zoom;
  lv_offline_map_location_result_t result;

  if (ui == NULL || ui->map_widget == NULL)
    {
      return;
    }

  if (ui->location_marker != NULL)
    {
      lv_obj_add_flag(ui->location_marker, LV_OBJ_FLAG_HIDDEN);
    }

  if (ui->location_label != NULL)
    {
      lv_obj_add_flag(ui->location_label, LV_OBJ_FLAG_HIDDEN);
    }

  if (!ui->location_state.valid)
    {
      return;
    }

  lon_e7 = qiban_ui_coord_to_e7(ui->location_state.longitude);
  lat_e7 = qiban_ui_coord_to_e7(ui->location_state.latitude);
  zoom = qiban_ui_effective_map_zoom(ui);
  memset(&result, 0, sizeof(result));
  if (ui->map_route_active &&
      lv_offline_map_track_get_point_count(ui->map_widget) >= 2 &&
      lv_offline_map_track_update_location_e7(ui->map_widget, lon_e7, lat_e7,
                                              zoom, &result))
    {
      return;
    }

  lv_offline_map_set_vehicle_location_e7(ui->map_widget, lon_e7, lat_e7,
                                         zoom, false);
}

