static void qiban_ui_map_pan_event_cb(lv_event_t *event)
{
  FAR const char *direction;
  lv_obj_t *container;
  lv_coord_t dx;
  lv_coord_t dy;

  if (lv_event_get_code(event) != LV_EVENT_CLICKED)
    {
      return;
    }

  if (g_qiban_ui == NULL || g_qiban_ui->map_widget == NULL)
    {
      return;
    }

  direction = (FAR const char *)lv_event_get_user_data(event);
  container = lv_offline_map_get_container(g_qiban_ui->map_widget);
  if (direction == NULL || container == NULL)
    {
      return;
    }

  dx = 0;
  dy = 0;
  if (strcmp(direction, "left") == 0)
    {
      dx = -QIBAN_OFFLINE_MAP_PAN_STEP;
    }
  else if (strcmp(direction, "right") == 0)
    {
      dx = QIBAN_OFFLINE_MAP_PAN_STEP;
    }
  else if (strcmp(direction, "up") == 0)
    {
      dy = -QIBAN_OFFLINE_MAP_PAN_STEP;
    }
  else if (strcmp(direction, "down") == 0)
    {
      dy = QIBAN_OFFLINE_MAP_PAN_STEP;
    }
  else
    {
      return;
    }

  lv_obj_scroll_by(container, dx, dy, LV_ANIM_ON);
  qiban_ui_set_map_pending(g_qiban_ui, "地图已平移");
}

