    }

  errno = 0;
  value = strtol(text, &endptr, 10);
  if (text == endptr || errno != 0)
    {
      return -EINVAL;
    }

  while (*endptr == ' ' || *endptr == '\t' || *endptr == '\n' ||
         *endptr == '\r')
    {
      endptr++;
